class FakeDevice:
    """A shared state backend allows independent identity and restoration assertions."""
    def __init__(self):
        self.state = {"on": False, "bri": 117,
                      "seg": [{"id": 0, "col": [[12, 34, 56, 78], [1, 2, 3, 4], [0, 0, 0, 0]]}]}
        self.info = {"mac": "aabbccddeeff", "ble": {"protocol": 1, "maxRequest": 4096},
                     "uptime": 100, "freeheap": 65000}
        self.posts = []
        self.connect_fails = False
        self.live = []
        self.subscribed = False

    def snapshot(self):
        return copy.deepcopy({"state": self.state, "info": self.info})

    def update(self, update):
        self.posts.append(copy.deepcopy(update))
        was_on = self.state["on"]
        if "on" in update:
            self.state["on"] = update["on"]
        if "bri" in update:
            if update["bri"] == 0:
                self.state["on"] = False
            else:
                self.state["bri"] = update["bri"]
        if self.state["on"] and not was_on:
            for segment in self.state["seg"]:
                if "frz" in segment:
                    segment["frz"] = False
        for segment in update.get("seg", []):
            existing = next(s for s in self.state["seg"] if s["id"] == segment["id"])
            existing["col"][:len(segment["col"])] = copy.deepcopy(segment["col"])
            if "frz" in segment:
                existing["frz"] = segment["frz"]
        if self.subscribed:
            self.live.append(self.snapshot())


class FakeClient:
    """Only the public runner contract is emulated; protocol correctness has separate tests."""
    def __init__(self, device, **kwargs):
        self.device = device
        self.timeout = kwargs["timeout"]
        self.write_budget = kwargs["chunk_size"]
        self.client = self
        self.is_connected = False

    async def connect(self):
        if self.device.connect_fails:
            raise ConnectionError("sensitive payload must not be printed")
        self.is_connected = True

    async def disconnect(self):
        self.is_connected = False

    async def request(self, method, path, body=""):
        if not self.is_connected:
            raise ConnectionError("Disconnected")
        method = method.upper()
        path = path.split("?")[0].rstrip("/")
        status = 200
        value = {}
        if method == "GET":
            if path in ("/json", "/json/si"):
                value = self.device.snapshot()
            elif path == "/json/state":
                value = self.device.state
            elif path == "/json/info":
                value = self.device.info
            elif path in ("/json/effects", "/json/fxdata"):
                value = ["test"]
            elif path == "/json/cfg":
                value = {"wifi": {"password": "DO-NOT-LOG"}, "pairing-code": "654321"}
            elif path != "/json/pins":
                status = 404
        elif method == "POST":
            if path not in ("/json", "/json/state"):
                status = 404
            else:
                try:
                    update = json.loads(body)
                    if not isinstance(update, dict):
                        raise ValueError()
                except ValueError:
                    status = 400
                else:
                    self.device.update(update)
                    value = self.device.snapshot() if update.get("v") else {"success": True}
        else:
            status = 405
        return bridge.BridgeResponse(status, "application/json", json.dumps(value))

    async def subscribe_live(self):
        self.device.subscribed = True
        self.device.live = [self.device.snapshot()]

    async def unsubscribe_live(self):
        self.device.subscribed = False

    async def next_live(self, timeout=None):
        if not self.device.live:
            raise TimeoutError()
        return self.device.live.pop(0)

    async def stop_notify(self, uuid):
        pass

    async def start_notify(self, uuid, callback):
        self.raw_callback = callback

    async def write_gatt_char(self, uuid, data, response=True):
        if getattr(self.device, "fault_reply", False):
            self.raw_callback(None, bytearray(b"unexpected TX"))
        self.is_connected = False


class FakeOracle:
    def __init__(self, device):
        self.device = device
        self.closed = False

    async def open(self):
        pass

    async def close(self):
        self.closed = True

    async def snapshot(self, update=None):
        if update is not None:
            self.device.update(update)
        return self.device.snapshot()


class RunnerTests(unittest.IsolatedAsyncioTestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.addCleanup(self.directory.cleanup)
        self.args = hil.parse_args(["--address", "test", "--output", self.directory.name])
        self.device = FakeDevice()

    def runner(self, oracle=None):
        return hil.HilRunner(self.args, client_factory=lambda _address, **kwargs: FakeClient(self.device, **kwargs),
                             oracle=oracle)

    async def test_smoke_restores_baseline_and_never_persists_configuration(self):
        before = copy.deepcopy(self.device.state)
        oracle = FakeOracle(self.device)
        runner = self.runner(oracle)
        self.assertEqual(await runner.run(), 0)
        self.assertEqual(self.device.state, before)
        self.assertTrue(oracle.closed)
        self.assertFalse(runner.client.is_connected)
        for path in pathlib.Path(self.directory.name).iterdir():
            text = path.read_text()
            self.assertNotIn("DO-NOT-LOG", text)
            self.assertNotIn("654321", text)
        result = json.loads((pathlib.Path(self.directory.name) / "results.json").read_text())
        self.assertEqual(result["outcome"], "passed_selected_coverage")
        self.assertEqual(result["lifecycle"], "finished")
        self.assertIsNotNone(result["finished_utc"])
        self.assertTrue(result["coverage_limits"])
        self.assertEqual(len(result["health_samples"]), 2)
        self.assertEqual(next(r for r in result["records"] if r["name"] == "final_health")["status"], "pass")

    async def test_missing_oracle_is_incomplete_not_pass(self):
        runner = self.runner()
        self.assertEqual(await runner.run(), 2)
        self.assertEqual(next(r for r in runner.records if r["name"] == "independent_oracle")["status"], "skip")
        self.assertEqual(json.loads((pathlib.Path(self.directory.name) / "results.json").read_text())["outcome"], "incomplete")

    async def test_wrong_oracle_mac_blocks_all_state_writes(self):
        wrong = FakeDevice()
        wrong.info["mac"] = "112233445566"
        runner = self.runner(FakeOracle(wrong))
        self.assertEqual(await runner.run(), 1)
        self.assertEqual(self.device.posts, [])
        self.assertEqual(wrong.posts, [])
        self.assertIsNone(runner.baseline)

    async def test_setup_failure_still_creates_all_reports(self):
        self.device.connect_fails = True
        runner = self.runner()
        self.assertEqual(await runner.run(), 1)
        for filename in ("results.json", "junit.xml", "report.md", "cases.jsonl"):
            path = pathlib.Path(self.directory.name) / filename
            self.assertTrue(path.is_file())
            self.assertNotIn("sensitive payload", path.read_text())

    async def test_successful_recovery_preserves_original_failure(self):
        runner = self.runner()
        await runner.setup()

        async def broken():
            raise AssertionError("Deliberate observed defect")

        self.assertFalse(await runner.case("broken", broken))
        self.assertEqual(runner.records[-1]["status"], "fail")
        self.assertEqual(runner.records[-1]["recovery"], [{"attempt": 1, "status": "pass"}])
        self.assertEqual(runner.exit_code(), 1)
        await runner.disconnect()

    async def test_failed_recovery_stops_after_two_attempts(self):
        runner = self.runner()
        await runner.setup()
        self.device.connect_fails = True

        async def broken():
            raise TimeoutError()

        await runner.case("broken", broken)
        self.assertTrue(runner.aborted)
        self.assertEqual(len(runner.records[-1]["recovery"]), 2)

    async def test_uptime_rollback_is_failure(self):
        runner = self.runner()
        await runner.setup()
        self.device.info["uptime"] = 1
        with self.assertRaisesRegex(AssertionError, "unexpected restart"):
            await runner.sample()
        await runner.disconnect()

    async def test_restore_rejects_independent_readback_mismatch(self):
        oracle = FakeOracle(self.device)
        runner = self.runner(oracle)
        await runner.setup()
        await runner.post({"bri": 42})
        original_snapshot = oracle.snapshot

        async def wrong_readback(update=None):
            value = await original_snapshot(update)
            value["state"]["bri"] = 43
            return value

        oracle.snapshot = wrong_readback
        with self.assertRaisesRegex(AssertionError, "Independent oracle: baseline"):
            await runner.restore()
        await runner.disconnect()

