    def test_serial_panic_causes_failure_without_persisting_raw_text(self):
        oracle = hil.SerialOracle("unused", 0.1)
        oracle.serial = Mock()
        oracle.serial.in_waiting = 50
        oracle.serial.read.return_value = b"Guru Meditation sensitive-content-that-must-not-be-recorded"
        oracle.serial.read_until.return_value = b'{"state":{},"info":{}}\n'
        with self.assertRaisesRegex(AssertionError, "Serial crash"):
            oracle._snapshot(None)
        self.assertEqual(oracle.events[0]["event"], "panic")
        self.assertNotIn("sensitive-content", json.dumps(oracle.events))

    async def test_lifecycle_remains_running_until_cleanup_finishes_even_on_setup_failure(self):
        for setup_fails in (False, True):
            with self.subTest(setup_fails=setup_fails):
                self.args.output = str(pathlib.Path(self.directory.name) / str(setup_fails))
                self.device.connect_fails = setup_fails
                oracle = FakeOracle(self.device)
                entered = asyncio.Event()
                release = asyncio.Event()

                async def blocked_close():
                    entered.set()
                    await release.wait()
                    oracle.closed = True

                oracle.close = blocked_close
                runner = self.runner(oracle)
                task = asyncio.create_task(runner.run())
                try:
                    await asyncio.wait_for(entered.wait(), 2)
                    path = pathlib.Path(self.args.output) / "results.json"
                    result = json.loads(path.read_text())
                    self.assertEqual(result["lifecycle"], "running")
                    self.assertEqual(result["outcome"], "running")
                    self.assertIsNone(result["finished_utc"])
                finally:
                    release.set()
                    await task
                result = json.loads(path.read_text())
                self.assertEqual(result["lifecycle"], "finished")
                self.assertEqual(result["outcome"], "failed" if setup_fails else "passed_selected_coverage")
                self.assertIsNotNone(result["finished_utc"])

    def test_source_metadata_is_captured_once_and_not_changed_by_later_edits(self):
        with tempfile.TemporaryDirectory() as source_dir:
            source = pathlib.Path(source_dir) / "sample.py"
            source.write_text("original source")
            original_capture = hil.capture_source_metadata
            with patch.object(hil, "capture_source_metadata", side_effect=lambda: original_capture(source_dir)) as capture:
                runner = self.runner()
                expected = hashlib.sha256(source.read_bytes()).hexdigest()
                source.write_text("edited while the run is active")
                runner.write_reports()
                runner.finish_reports()
                capture.assert_called_once_with()
            result = json.loads((pathlib.Path(self.directory.name) / "results.json").read_text())
            self.assertEqual(result["source_sha256"], {"sample.py": expected})

    def test_nonempty_output_is_rejected_without_touching_existing_evidence(self):
        evidence = pathlib.Path(self.directory.name) / "results.json"
