        factory = Mock()
        with self.assertRaisesRegex(FileExistsError, "not empty"):
            hil.HilRunner(self.args, client_factory=factory)
        factory.assert_not_called()
        self.assertEqual(evidence.read_text(), "previous evidence")
        self.assertEqual([path.name for path in pathlib.Path(self.directory.name).iterdir()], ["results.json"])

