    async def test_soak_operation_names_and_summary_describe_real_api_work(self):
        self.args.duration = 0.01
        runner = self.runner()
        await runner.setup()
        runner.rng = Mock()
        runner.rng.randrange.return_value = 0
        runner.rng.randint.return_value = 74
        await runner.soak()
        runner.finish_reports()
        record = runner.records[-1]
        self.assertTrue(record["name"].endswith("_brightness_readback"))
