    def test_heap_summary_describes_warmup_and_final_plateau_without_verdict(self):
        values = [1000, 900, 800, 800, 800, 800, 800, 800]
        summary = hil.health_summary([{"at": index * 60, "uptime": index * 60, "freeheap": value}
                                      for index, value in enumerate(values)])
        metric = summary["heap_metrics"]["freeheap"]
        self.assertEqual(metric["net_change_bytes"], -200)
        self.assertEqual(metric["final_quarter"]["trend_bytes_per_minute"], 0)
        self.assertEqual(metric["final_quarter"]["range_bytes"], 0)
        self.assertEqual(set(summary["heap_metrics"]), {"freeheap"})
        self.assertNotIn("status", metric)
        self.assertNotIn("pass", metric)


